// Command gen-prompts regenerates internal/mcp/server/prompts_gen.go from the
// mage2mcp skill references.
//
// The references under skills/mage2mcp/references are the single source of truth:
// the MCP prompts the server exposes and the skill a repository reader loads are
// generated from the same text, so they cannot drift. Run with -write to update
// the checked-in file; without it the generated file is printed to stdout.
package main

import (
	"bytes"
	"flag"
	"fmt"
	"go/format"
	"os"
	"path/filepath"
	"strings"
)

const (
	// referencesDir is the source of truth. Every prompt body is one file there.
	referencesDir = "skills/mage2mcp/references"
	// outputPath is the generated Go file the server compiles.
	outputPath = "internal/mcp/server/prompts_gen.go"
)

// promptSource maps one MCP prompt to the reference file it is generated from.
type promptSource struct {
	// Name is the prompt name a client asks for.
	Name string
	// Title is the one-line title shown by prompts/list.
	Title string
	// Description is the prompts/list description: when to load this prompt.
	Description string
	// File is the reference file name under referencesDir.
	File string
	// Const is the Go constant that carries the body.
	Const string
}

// promptSources is the fixed prompt surface. A new prompt means a new reference
// file and a new row here; the drift test fails until both exist.
var promptSources = []promptSource{
	{
		Name:        "write_contract",
		Title:       "Write contract",
		Description: "Two-step approval, idempotency, and what each error code licenses. Load before any write.",
		File:        "write-contract.md",
		Const:       "writeContractPrompt",
	},
	{
		Name:        "refunds",
		Title:       "Refunds and credit memos",
		Description: "Refund one line or the rest, shipping defaults, and what a refund is not.",
		File:        "refunds.md",
		Const:       "refundsPrompt",
	},
	{
		Name:        "reports",
		Title:       "Sales reports",
		Description: "What revenue, refunds and day buckets mean, and how to report truncation honestly.",
		File:        "reports.md",
		Const:       "reportsPrompt",
	},
	{
		Name:        "imports",
		Title:       "Bulk imports",
		Description: "CSV row rules, the async job lifecycle, and the bulk_update trap.",
		File:        "imports.md",
		Const:       "importsPrompt",
	},
	{
		Name:        "product_copy",
		Title:       "Copy products from another store",
		Description: "The full copy recipe: discover the source, check the target, create in order, verify like a shopper.",
		File:        "product-copy.md",
		Const:       "productCopyPrompt",
	},
	{
		Name:        "write_safety",
		Title:       "Write safety and URL structure",
		Description: "Checklist before writes that change catalog structure, product URLs or attribute semantics.",
		File:        "catalog-safety.md",
		Const:       "writeSafetyPrompt",
	},
}

// Generate renders prompts_gen.go from the reference files, relative to the
// repository root (the directory the command is documented to run from).
func Generate() ([]byte, error) { return GenerateAt(".") }

// GenerateAt renders prompts_gen.go with the references resolved under root, so
// tests can run from their own package directory.
func GenerateAt(root string) ([]byte, error) {
	var body bytes.Buffer
	body.WriteString("// Code generated by scripts/gen-prompts from skills/mage2mcp/references; DO NOT EDIT.\n")
	body.WriteString("//\n")
	body.WriteString("// The references are the single source of truth: edit them and run\n")
	body.WriteString("// `go run ./scripts/gen-prompts -write`, never this file.\n\n")
	body.WriteString("package server\n\n")
	body.WriteString("// promptText is one generated MCP prompt: the name a client asks for, the\n")
	body.WriteString("// metadata prompts/list shows, and the body it receives.\n")
	body.WriteString("type promptText struct {\n\tName string\n\tTitle string\n\tDescription string\n\tBody string\n}\n\n")

	for _, source := range promptSources {
		path := filepath.Join(root, referencesDir, source.File)
		// G304: the path is filepath.Join(root, referencesDir, source.File) where
		// source.File comes from the fixed promptSources table below and root is the
		// repository root passed by the caller; no user-controlled path reaches it.
		raw, err := os.ReadFile(path) //nolint:gosec // see above
		if err != nil {
			return nil, fmt.Errorf("read %s: %w", path, err)
		}
		text := strings.TrimRight(string(raw), "\n")
		if strings.TrimSpace(text) == "" {
			return nil, fmt.Errorf("%s is empty", path)
		}
		lines := make([]string, 0, 64)
		for _, line := range strings.SplitAfter(text, "\n") {
			if line == "" {
				continue
			}
			lines = append(lines, quote(line))
		}
		body.WriteString("const " + source.Const + " = \"\" +\n")
		for i, line := range lines {
			body.WriteString("\t" + line)
			if i < len(lines)-1 {
				body.WriteString(" +\n")
			} else {
				body.WriteString("\n")
			}
		}
		body.WriteString("\n")
	}

	body.WriteString("// generatedPrompts is the prompt surface, derived from the skill references.\n")
	body.WriteString("var generatedPrompts = []promptText{\n")
	for _, source := range promptSources {
		fmt.Fprintf(&body, "\t{Name: %q, Title: %q, Description: %q, Body: %s},\n",
			source.Name, source.Title, source.Description, source.Const)
	}
	body.WriteString("}\n")

	formatted, err := format.Source(body.Bytes())
	if err != nil {
		return nil, fmt.Errorf("gofmt generated source: %w", err)
	}
	return formatted, nil
}

// quote renders one line as a Go string literal, keeping the trailing newline.
func quote(line string) string {
	return fmt.Sprintf("%q", line)
}

func main() {
	write := flag.Bool("write", false, "write the generated file to -path")
	path := flag.String("path", outputPath, "generated Go file path")
	flag.Parse()

	data, err := Generate()
	if err != nil {
		fmt.Fprintln(os.Stderr, "gen-prompts:", err)
		os.Exit(1)
	}
	if !*write {
		_, _ = os.Stdout.Write(data)
		return
	}
	// The output is a generated Go source file committed to the repository, so it
	// must stay world-readable like the rest of the tree.
	if err := os.WriteFile(*path, data, 0o644); err != nil { //nolint:gosec // G306: generated source, not a secret
		fmt.Fprintln(os.Stderr, "gen-prompts:", err)
		os.Exit(1)
	}
	fmt.Fprintf(os.Stderr, "wrote %s\n", *path)
}
